  'staticcheck': 'staticcheck is a Go static-analysis suite for correctness, simplification, performance, and deprecation issues.',
  'Delve debugger': 'Delve is a debugger for Go supporting breakpoints, stepping, goroutine inspection, and core dumps.',

  // Standard library
  'fmt': 'fmt implements formatted I/O and the Stringer, error-formatting, and scanning conventions.',
  'encoding/xml': 'encoding/xml marshals and unmarshals XML using exported fields, tags, tokens, and streaming decoders.',
  'os': 'os provides portable process, environment, file, signal, and filesystem operations.',
  'io': 'io defines small Reader, Writer, Closer, Seeker, and copying interfaces used throughout Go.',
