for (const [name, definition] of Object.entries(remainingDefinitions)) {
  if (!interviewFacts[name]) interviewFacts[name] = [definition, `What is ${name}, and what is its main production concern?`, definition];
}

for (const [alias, target] of Object.entries(aliases)) {
  if (interviewFacts[target] && !interviewFacts[alias]) interviewFacts[alias] = interviewFacts[target];
}
